+import { add } from "./math.js";
+
+export function perimeter(width, height) {
+  return 2 * add(width, height);
+}
+
+export function area(width, height) {
+  return width * height;
+}
+
+export function circleArea(radius) {
+  return Math.PI * radius * radius;
+}

